def has_uniform_region(g, r, c, h, w):
    """Check if there's a uniform region of size h x w starting at (r, c)."""
    for i in range(r, r+h):
        for j in range(c, c+w):
            if g[i][j] == 0:
                return False, 0
    return True, g[r][c]

