def find_l_shapes(g):
    """Find regions where corners align in an L-shape pattern."""
    results = []
    rows, cols = len(g), len(g[0])

    for r in range(rows):
        for c in range(cols):
            val = g[r][c]
            if val == 0:
                continue
            # Check if it's a horizontal bar of 3+ cells
            hbar = []
            for wc in range(cols - c):
                if g[r][c + wc] == val:
                    hbar.append(c + wc)
                else:
                    break
            # Check if it's a vertical bar of 3+ cells
            vbar = []
            for hr in range(rows - r):
                if g[r + hr][c] == val:
                    vbar.append(r + hr)
                else:
                    break

            if len(hbar) >= 2 and len(vbar) >= 2:
                # Found corner
                results.append((r, c, val, hbar, vbar))

    return results

